%[text] # 时变特性周期噪声的自适应反馈控制（Jafari & Ioannou, 2015）
%%
%[text] ## 理论背景
%[text] 脚本是对Saeid Jafari, Petros Ioannou和Lael Rudd 2015年JVC论文的仿真复现。文章设计的控制器结构包含$F\\left(s\\right)${"editStyle":"visual"}与$K\\left(s,\\theta \\right)${"editStyle":"visual"}两部分，非常简单。以下内容按照原文分节，通过易于理解循序渐进的仿真复现过程。
%%
%[text] ## 1 固定控制器设计
%[text] 引入固定控制器$F\\left(s\\right)${"editStyle":"visual"}的目的是为了在$\\omega \\in \\left\\lbrack 0,{\\bar{\\;\\omega \\;} }\_{\\max } \\right\\rbrack${"editStyle":"visual"}上尽可能展平$W\\left(s\\right)=F\\left(s\\right)G\_{0\\;} \\left(s\\right)\\Lambda \\;\\left(s\\right)${"editStyle":"visual"}的频谱。
%[text] 由于其中$\\Lambda \\left(s\\right)${"editStyle":"visual"}的各对角元素均为直流增益1，且带宽$\>{\\bar{\\;\\omega \\;} }\_{\\max }${"editStyle":"visual"}的低通滤波器，只需要合理地选取$F\\left(s\\right)${"editStyle":"visual"}使得$G\_0^{\\prime } \\left(s\\right)${"editStyle":"visual"}在带宽内具有足够带的增益即可。
%[text] 作者给出的构造过程如下：
%[text] 1. 先取$\\tilde{G\_0 } \\left(s\\right)=G\_{0\\;} \\left(s\\right)${"editStyle":"visual"}；
%[text] 2. 假如$\\tilde{G\_0 } \\left(s\\right)${"editStyle":"visual"}有虚轴零点，则将其平移至LHP$s=-\\delta\_0 \\pm j\\omega\_0${"editStyle":"visual"}，其中$\\delta\_0${"editStyle":"visual"}是一个小的正实数；
%[text] 3. 假如$\\tilde{G\_0 } \\left(s\\right)${"editStyle":"visual"}有不稳定零点$s=\\sigma\_0 \\pm j\\omega\_0${"editStyle":"visual"}，则将其反射至LHP$s=-\\sigma\_0 \\pm j\\omega\_0${"editStyle":"visual"}.
%[text] 4. 最后，取$F\\left(s\\right)=\\kappa\_0 \\frac{\\alpha^m }{{\\left(s+\\alpha \\right)}^m }\\tilde{\\;G\_0^{-1} } \\left(s\\right)${"editStyle":"visual"} \
% 定义示例中的G0(s)
modelFile_ex = fullfile('..', 'dataset', 'syn_JVC2017_6th.mat');
load(modelFile_ex, 'model');
G0 = model.G0;
s = tf('s');
pzmap(G0); grid on; title('G_0(s) 零极点分布');
bodemag(G0); grid on; title('G_0(s) 幅频响应');
% 设计滤波器F(s)
F = designLTIFilter(G0, 1, 0.01, 300, 2, 300)
bodemag(F*G0); grid on; title('F(s)G_0(s) 幅频响应 (频谱展平后)');
%%
%[text] ## 2 自适应控制器设计
%[text] 文中的自适应滤波器设计为：$K\\left(s,\\theta \\;\\left(t\\right)\\right)=\\sum\_{k=0}^{N-1} \\theta\_k \\left(t\\right)\\frac{\\lambda^{N-k} }{{\\left(s+\\lambda \\right)}^{N-k} }${"editStyle":"visual"}。这一滤波器组由多个低通滤波器并联而成，每一级低通滤波器增益参数作为自适应参数。为便于理解参数对自适应参数的作用，提供绘图分析：
%[text] 举例而言，若取$N=5${"editStyle":"visual"}，$\\lambda =500${"editStyle":"visual"}，滤波器组如下：
% 自适应滤波器组Bode图绘制示例
N = 5;
lambda = 500;
s = tf('s');
Ts = 1/10000; % 可选采样周期，若需离散化可用c2d

figure; hold on;
colors = lines(N);
for k = 1:N
    num = lambda^(N-k+1);
    den = (s + lambda)^(N-k+1);
    Hk = num / den;
    [mag, phase, w] = bode(Hk, {1e-3, 1e3});
    mag = squeeze(mag);
    phase = squeeze(phase);
    semilogx(w/(2*pi), 20*log10(mag), 'Color', colors(k,:), 'LineWidth', 2, ...
        'DisplayName', sprintf('k=%d', k-1));
end
xlabel('Frequency (Hz)');
ylabel('Magnitude (dB)');
title('自适应滤波器组 Bode 图');
legend show; grid on;
%[text] 为实现滤波器权重系数的自适应，设计如下的观测与参数自适应环节：
%[text] 对$\\hat{z} =\\theta {\\;}^{\\top \\;} \\phi${"editStyle":"visual"}选用最小二乘算法
%[text] $\\dot{P} \\left(t\\right)=-P\\frac{\\phi \\phi^{\\top \\;} }{1+\\gamma\_0 \\phi^{\\top \\;} \\phi \\;}P${"editStyle":"visual"}
%[text] $\\varepsilon =\\frac{\\left(z-\\hat{z} \\right)}{1+\\gamma\_0 \\phi^{\\top \\;} \\phi \\;}${"editStyle":"visual"}
%[text] $\\dot{\\theta \\;} \\left(t\\right)=\\textrm{Proj}\\left(P\\varepsilon \\phi \\right)=\\left\\lbrace \\begin{array}{ll}\nP\\varepsilon \\phi  & \\theta \\in {\\mathbb{S}}\_0 \\;\\textrm{or}\\;\\theta \\in \\delta \\mathbb{S}\\;\\textrm{and}\\;{\\left(P\\varepsilon \\phi \\right)}^{\\top \\;} \\nabla g\\le 0\\\\\nP\\varepsilon \\phi -P\\frac{\\nabla g\\nabla g^{\\top \\;} }{\\nabla g^{\\top \\;} P\\nabla g}P\\varepsilon \\phi  & \\textrm{otherwise}\n\\end{array}\\right.${"editStyle":"visual"}
%[text] 其中，${\\mathbb{S}}\_0 =\\left\\lbrace \\theta \\in {\\mathbb{R}}^N |g\\left(\\theta \\right)=\\theta^{\\top \\;} \\theta -\\theta\_{\\max }^2 \<0\\right\\rbrace${"editStyle":"visual"}而$\\delta \\mathbb{S}=\\left\\lbrace \\theta \\in {\\mathbb{R}}^N |g\\left(\\theta \\right)=\\theta^{\\top \\;} \\theta -\\theta\_{\\max }^2 =0\\right\\rbrace${"editStyle":"visual"}，分别表示$\\mathbb{S}${"editStyle":"visual"}的内部和边界。
%%
%[text] ## 3 完整的数值仿真实验
%[text] ### （1）问题设置
clear; close all; clc;
addpath('..\functions');
%% 参数设置
fs = 10000;              % 采样频率 [Hz]
Ts = 1/fs;              % 采样周期
Tsim = 20;               % 仿真总时间 [s]
Nsim = Tsim*fs;         % 仿真步数
t = (0:Nsim-1)*Ts;

%% 1. 定义名义模型 G0 和不确定性
modelFile = fullfile('..', 'dataset', 'syn_JVC2017_3rd.mat');
load(modelFile, 'model');
G0 = model.G0;                              % 名义模型
s = tf('s');
epsi = 0.001;           % 不确定性幅度
Delta = epsi*s;
G = minreal(G0*(1+Delta)); % 实际模型

%% 2. 扰动信号 d(t)
% 固定频率分量
A = [0.6 0.7];          % 幅值
omega = [70, 187];      % rad/s (论文扰动频率)
phi = [pi/4 pi/2];      % 相位
d = zeros(1,Nsim);
for k=1:length(A)
    d = d + A(k)*sin(omega(k)*t + phi(k));
end
% 加入小随机噪声
d = d + 0.02*randn(1,Nsim);

bodemag(G); grid on; title('实际模型 G(s) 幅频响应');
bodemag(1/(1+G)); grid on; title('灵敏度函数 S(s)=1/(1+G) 幅频响应');
%%
%[text] ### （2）固定控制器设计
%% 3. 控制器结构 (F(s)+K(s,theta))
% 固定滤波器 F(s)
k0 = 0.5;
delta0 = 0.; 
alpha = 500; 
m = 2;
omega_max = 600;
F = designLTIFilter(G0, k0, delta0, alpha, m, omega_max)
% 离散化 F(s)
Fd = c2d(F, Ts, 'tustin');
[numF, denF] = tfdata(Fd, 'v');
stateF = zeros(max(length(denF), length(numF))-1, 1);
bodemag(F); grid on; title('固定滤波器 F(s) 幅频响应');
bodemag(F*G0); grid on; title('F(s)G_0(s) 幅频响应 (频谱展平后)');
%%
%[text] ### （2）自适应控制器设计
% K(s,theta) 参数化（简化成 FIR 滤波器）
Nparam = 20;  lambda_val = 500;
G1_d = c2d(tf(lambda_val,[1 lambda_val]), Ts, 'tustin');
[numG1, denG1] = tfdata(G1_d, 'v');
Gd_s  = c2d(G,  Ts, 'tustin'); [numGd_s,  denGd_s]  = tfdata(Gd_s,  'v');
G0d_s = c2d(G0, Ts, 'tustin'); [numG0d_s, denG0d_s] = tfdata(G0d_s, 'v');

%% ====== 第1段: Lambda基 + Euler离散梯度 ======
P_euler = eye(Nparam) * 500;  gamma0 = 1.0;  theta_max_val = 5;
theta1 = zeros(Nparam, 1);
nF  = max(length(numF), length(denF)) - 1;
nG0 = max(length(numG0d_s), length(denG0d_s)) - 1;
Lam_zf1=zeros(Nparam,1); phi_F_zf1=zeros(Nparam,nF); phi_G0_zf1=zeros(Nparam,nG0);
G_zf1=zeros(max(length(numGd_s),length(denGd_s))-1,1); G0_zf1=zeros(nG0,1); F_zf1=zeros(nF,1);
y1=zeros(1,Nsim); u1=zeros(1,Nsim); plant1=zeros(1,Nsim); z_hist1=zeros(1,Nsim);
theta_hist1=zeros(Nparam,Nsim); P_tr1=zeros(1,Nsim);

fprintf('第1段 (Lambda+Euler): N=%d, lambda=%.0f, theta_max=%.0f, 扰动=[%.0f, %.0f] rad/s\\n', Nparam, lambda_val, theta_max_val, omega(1), omega(2));
lam1=zeros(Nparam,1); phi1=zeros(Nparam,1);

for k = 2:Nsim
    [y_G_k, G_zf1] = filter(numGd_s, denGd_s, u1(k-1), G_zf1);
    plant1(k)=y_G_k; y1(k)=y_G_k+d(k);
    [G0_u_k, G0_zf1] = filter(numG0d_s, denG0d_s, u1(k-1), G0_zf1);
    z_k=y1(k)-G0_u_k; z_hist1(k)=z_k;
    ys=z_k;
    for stage=1:Nparam
        [ys, Lam_zf1(stage)]=filter(numG1,denG1,ys,Lam_zf1(stage));
        lam1(Nparam-stage+1)=ys;
    end
    for i=1:Nparam
        [fo,phi_F_zf1(i,:)]=filter(numF,denF,lam1(i),phi_F_zf1(i,:)');
        [phi1(i),phi_G0_zf1(i,:)]=filter(numG0d_s,denG0d_s,fo,phi_G0_zf1(i,:)');
    end
    m2=1+gamma0*(phi1.'*phi1); eps1=(z_k-theta1.'*phi1)/m2;
    Pph=P_euler*phi1; P_euler=P_euler-Ts*(Pph*Pph.')/m2;
    th_new=theta1+Ts*P_euler*eps1*phi1; thn=norm(th_new);
    theta1=th_new*min(1,theta_max_val/thn);
    theta_hist1(:,k)=theta1; P_tr1(k)=trace(P_euler);
    [u1(k),F_zf1]=filter(numF,denF,-theta1.'*lam1,F_zf1);
    if mod(k,round(Nsim/4))==0
        fprintf('  t=%.1fs: ||th||=%.3f, tr(P)=%.2e\n',t(k),thn,trace(P_euler));
    end
end

fin1=round(0.5*Nsim):Nsim;
rms_y1=sqrt(mean(y1(fin1).^2)); rms_d=sqrt(mean(d(fin1).^2));
supp1=20*log10(rms_y1/rms_d);
fprintf('第1段(Lambda+Euler): 抑制=%.1f dB, ||th||=%.3f\n', supp1, norm(theta1));

figure('Name','第1段: Lambda+Euler 离散梯度法');
subplot(3,1,1); plot(t,d,'Color',[.7 .7 .7]); hold on; plot(t,plant1,'r--'); plot(t,y1,'b-');
xline(0.5*Tsim, 'k--', '稳态评估起点', 'LineWidth', 1);
legend('d','G输出','y', 'Location', 'best');
title(sprintf('输出信号 (抑制 %.1f dB)', supp1)); grid on;
subplot(3,1,2); plot(t,u1,'g-');
title(sprintf('控制输入 u(t) (RMS=%.2f)', rms(u1(fin1)))); grid on;
subplot(3,1,3); plot(t,theta_hist1(1:5:end,:)');
title(sprintf('\\theta(t) 演化 (||\\theta||=%.2f)', norm(theta1))); grid on;
sgtitle('Jafari JVC — 第1段: Lambda+Euler 离散梯度法');

%% ====== 第2段: Lambda基 + 归一化RLS ======
P_rls=eye(Nparam)*0.5; theta_max_r=5; gamma0_r=1.0; theta2=zeros(Nparam,1);
Lam_zf2=zeros(Nparam,1); phi_F_zf2=zeros(Nparam,nF); phi_G0_zf2=zeros(Nparam,nG0);
G_zf2=zeros(max(length(numGd_s),length(denGd_s))-1,1); G0_zf2=zeros(nG0,1); F_zf2=zeros(nF,1);
y2=zeros(1,Nsim); u2=zeros(1,Nsim); plant2=zeros(1,Nsim);
theta_hist2=zeros(Nparam,Nsim); P_tr2=zeros(1,Nsim);

fprintf('\n===== 第2段: Lambda+RLS =====\n');
lam2=zeros(Nparam,1); phi2=zeros(Nparam,1);

for k=2:Nsim
    [y_G_k,G_zf2]=filter(numGd_s,denGd_s,u2(k-1),G_zf2);
    plant2(k)=y_G_k; y2(k)=y_G_k+d(k);
    [G0_u_k,G0_zf2]=filter(numG0d_s,denG0d_s,u2(k-1),G0_zf2);
    z_k=y2(k)-G0_u_k;
    ys=z_k;
    for stage=1:Nparam
        [ys,Lam_zf2(stage)]=filter(numG1,denG1,ys,Lam_zf2(stage));
        lam2(Nparam-stage+1)=ys;
    end
    for i=1:Nparam
        [fo,phi_F_zf2(i,:)]=filter(numF,denF,lam2(i),phi_F_zf2(i,:)');
        [phi2(i),phi_G0_zf2(i,:)]=filter(numG0d_s,denG0d_s,fo,phi_G0_zf2(i,:)');
    end
    m2=1+gamma0_r*(phi2.'*phi2); eps2=(z_k-theta2.'*phi2)/m2;
    Pph=P_rls*phi2; den=m2+phi2.'*Pph;
    if den>1e-12
        Kr=Pph/den; P_rls=P_rls-(Kr*Pph.');
        th_new=theta2+Kr*eps2; thn=norm(th_new);
        theta2=th_new*min(1,theta_max_r/thn);
    end
    theta_hist2(:,k)=theta2; P_tr2(k)=trace(P_rls);
    [u2(k),F_zf2]=filter(numF,denF,-theta2.'*lam2,F_zf2);
    if mod(k,round(Nsim/4))==0
        fprintf('  t=%.1fs: ||th||=%.3f, tr(P)=%.2e\n',t(k),thn,trace(P_rls));
    end
end

fin2=round(0.5*Nsim):Nsim;
rms_y2=sqrt(mean(y2(fin2).^2)); supp2=20*log10(rms_y2/rms_d);
rms_u2=sqrt(mean(u2(fin2).^2));
fprintf('第2段(Lambda+RLS): 抑制=%.1f dB, ||th||=%.3f, uRMS=%.0f\n', supp2, norm(theta2), rms_u2);

figure('Name','第2段: Lambda+RLS 归一化梯度法');
subplot(3,1,1); plot(t,d,'Color',[.7 .7 .7]); hold on; plot(t,plant2,'r--'); plot(t,y2,'b-');
xline(0.5*Tsim, 'k--', '稳态评估起点', 'LineWidth', 1);
legend('d','G输出','y', 'Location', 'best');
title(sprintf('输出信号 (抑制 %.1f dB)', supp2)); grid on;
subplot(3,1,2); plot(t,u2,'g-');
title(sprintf('控制输入 u(t) (RMS=%.2f)', rms_u2)); grid on;
subplot(3,1,3); plot(t,theta_hist2(1:5:end,:)');
title(sprintf('\\theta(t) 演化 (||\\theta||=%.2f)', norm(theta2))); grid on;
sgtitle('Jafari JVC — 第2段: Lambda+RLS 归一化梯度法');
%%
%[text] ## 5 附录
function F = designLTIFilter(G0, k0, delta0, alpha, m, omega_max)
% 设计LTI滤波器F(s)用于展平W(s) = F(s)G0(s)的频谱
%
% 输入参数:
%   G0       - 名义植物模型传递函数
%   k0       - 增益参数 (默认: 1)
%   delta0   - 设计常数（默认：0.01）
%   alpha    - 设计常数 (默认: 0.1)
%   m        - 相对度整数 (默认: 自动计算)
%   omega_max- 最大频率 (默认: 100 rad/s)
%
% 输出:
%   F        - 设计的LTI滤波器传递函数
%
% 设计步骤基于论文中的算法:
% 1. G̃0(s) = G0(s)
% 2. 如果G̃0(s)在虚轴上有零点，将其移动到左半平面
% 3. 如果G̃0(s)有不稳定零点，通过虚轴反射使其稳定
% 4. F(s) = k0 * (α^m/(s+α)^m) * G̃0^(-1)(s)

if nargin < 2, k0 = 1; end
if nargin < 3, delta0 = 0.01; end
if nargin < 4, alpha = 0.1; end
if nargin < 5, m = []; end
if nargin < 6, omega_max = 100; end

fprintf('=== LTI滤波器F(s)设计过程 ===\n');

% 获取G0的零极点
[z, p, k] = zpkdata(G0, 'v');
fprintf('原始G0零点: '); disp(z');
fprintf('原始G0极点: '); disp(p');
fprintf('原始G0增益: %.4f\n', k);

%% 步骤1: G̃0(s) = G0(s)
G_tilde = G0;
z_modified = z;

%% 步骤2: 处理虚轴上的零点
jw_zeros = abs(real(z)) < 1e-10; % 检测虚轴零点

if any(jw_zeros)
    fprintf('\n检测到虚轴零点，进行处理...\n');
    index = find(jw_zeros)';
    for i = index
        % 复数零点: s = ±jω0 → s = -δ0 ± jω0
        z_modified(i) = -delta0 + 1j*imag(z(i));
        fprintf('零点 %+.4f%+.4fi 移动到 %+.4f%+.4fi\n', ...
            real(z(i)), imag(z(i)), real(z_modified(i)), imag(z_modified(i)));
    end
end

%% 步骤3: 处理不稳定零点（右半平面零点）
rhp_zeros = real(z_modified) > 1e-10;

if any(rhp_zeros)
    fprintf('\n检测到不稳定零点，进行反射...\n');
    for i = find(rhp_zeros)
        z_old = z_modified(i);
        z_modified(i) = -real(z_modified(i)) + 1j*imag(z_modified(i));
        fprintf('零点 %+.4f%+.4fi 反射到 %+.4f%+.4fi\n', ...
            real(z_old), imag(z_old), real(z_modified(i)), imag(z_modified(i)));
    end
end

% 构造修改后的G̃0(s)
G_tilde = zpk(z_modified, p, k);
fprintf('\n修改后的G̃0(s): '); 
disp(G_tilde);

%% 步骤4: 计算相对度m (如果未指定)
if isempty(m)
    num_zeros = length(z_modified);
    num_poles = length(p);
    m = max(1, num_poles - num_zeros + 1); % 确保m > G̃0的相对度
    fprintf('自动计算的相对度 m = %d\n', m);
else
    fprintf('使用指定的相对度 m = %d\n', m);
end

%% 步骤5: 构造F(s)
s = tf('s');

% 低通滤波器部分: α^m/(s+α)^m
LPF = (alpha^m) / (s + alpha)^m;

% G̃0的逆: 1/G̃0(s)
G_tilde_inv = 1 / G_tilde;

% 完整的F(s)
F = k0 * LPF * G_tilde_inv;

% 化简传递函数
F = minreal(F);

fprintf('\n设计完成！\n');
fprintf('F(s) = k0 * (α^m/(s+α)^m) * G̃0^(-1)(s)\n');
fprintf('其中: k0=%.2f, α=%.2f, m=%d\n', k0, alpha, m);

end

